const LABELS: Record<string, string> = {
  upi: "UPI",
  card: "Card",
  netbanking: "Net Banking",
  wallet: "Wallet",
  emi: "Card EMI",
  cardless_emi: "Cardless EMI",
  paylater: "Pay Later",
};

export function paymentLabel(method: string | null) {
  return method ? LABELS[method] ?? method : "—";
}

export function PaymentBadge({ method, details }: { method: string | null; details: Record<string, string | number | null> | null }) {
  if (!method) return <p className="text-muted">Awaiting payment</p>;
  const d = details ?? {};
  const extra = [
    d.emiTenureMonths && `${d.emiTenureMonths}-month EMI`,
    d.emiIssuer && `via ${d.emiIssuer}`,
    d.provider && `via ${String(d.provider).replace(/_/g, " ")}`,
    d.cardNetwork && `${d.cardNetwork} ${d.cardType ?? ""}`.trim(),
    d.cardLast4 && `•••• ${d.cardLast4}`,
    d.bank && `Bank ${d.bank}`,
    d.wallet && String(d.wallet),
    d.upiHandle && String(d.upiHandle),
  ].filter(Boolean);
  return (
    <p>
      <span className="font-semibold">{paymentLabel(method)}</span>
      {extra.length > 0 && <span className="text-muted"> · {extra.join(" · ")}</span>}
    </p>
  );
}
